// Regenerates src/terminal/terminal-scripts.ts from the python PTY wrapper
// sources in scripts/terminal/. Run after editing either .py file:
//   node scripts/generate-terminal-scripts.mjs
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sources = [
  ["scripts/terminal/mv_terminal_pty.py", "TERMINAL_PTY_PY_BASE64"],
  ["scripts/terminal/mv_terminal_win.py", "TERMINAL_WIN_PY_BASE64"],
];

const lines = [
  "// Auto-generated by scripts/generate-terminal-scripts.mjs from scripts/terminal/*.py. Do not edit.",
  "",
];
for (const [relativePath, exportName] of sources) {
  const content = fs.readFileSync(path.join(root, relativePath));
  lines.push(`export const ${exportName} = '${content.toString("base64")}';`, "");
}
fs.writeFileSync(
  path.join(root, "src/terminal/terminal-scripts.ts"),
  lines.join("\r\n"),
);
console.log("Regenerated src/terminal/terminal-scripts.ts");
